style.css:
@-moz-document domain("youtube.com") {
/* --- Base HUD --- */
.ytp-chrome-bottom {
  background: rgba(40, 0, 60, 0.75) !important;
  backdrop-filter: blur(6px);
  border-top: 1px solid rgba(180, 120, 255, 0.3);
  height: 45px !important;
  transition: all 0.3s ease;
}

/* --- Buttons (Play, Settings, etc.) --- */
.ytp-button {
  filter: brightness(0) saturate(100%) invert(89%) sepia(73%) saturate(5351%) hue-rotate(240deg) brightness(103%) contrast(104%) !important;
  opacity: 0.8 !important;
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.ytp-button:hover {
  opacity: 1 !important;
  transform: scale(1.1);
}

/* --- Play/Pause Button --- */
.ytp-play-button {
  width: 40px !important;
  height: 40px !important;
}

/* --- Time Display --- */
.ytp-time-display {
  color: #d8b8ff !important;
  font-family: "Poppins", sans-serif !important;
  font-size: 13px !important;
  text-shadow: 0 0 4px #000;
}

/* --- Progress Bar --- */
.ytp-progress-bar-container {
  height: 6px !important;
}
.ytp-progress-bar {
  background: rgba(100, 50, 150, 0.6) !important;
}
.ytp-load-progress {
  background: rgba(160, 80, 255, 0.4) !important;
}
.ytp-play-progress {
  background: linear-gradient(90deg, #c77dff, #9d4edd) !important;
}
.ytp-scrubber-button {
  background: #e0b0ff !important;
  border: 2px solid #9d4edd !important;
  box-shadow: 0 0 8px #9d4edd !important;
}

/* --- Volume Panel --- */
.ytp-volume-slider-handle {
  background: #e0b0ff !important;
  border: 1px solid #9d4edd !important;
}
.ytp-volume-slider-handle:hover {
  background: #c77dff !important;
}
.ytp-volume-panel,
.ytp-volume-slider {
  background: rgba(80, 30, 120, 0.5) !important;
}

/* --- Settings, Subtitles, Fullscreen --- */
.ytp-settings-button,
.ytp-subtitles-button,
.ytp-fullscreen-button {
  filter: brightness(0) saturate(100%) invert(89%) sepia(73%) saturate(5351%) hue-rotate(240deg) brightness(103%) contrast(104%) !important;
}

/* --- Hover glow --- */
.ytp-button:hover svg path {
  filter: drop-shadow(0 0 6px #b88aff);
}

/* --- Hide extra clutter (optional) --- */
.ytp-gradient-bottom,
.ytp-pip-button,
.ytp-miniplayer-button,
.ytp-remote-button {
  display: none !important;
}
}
